"use client";

import { useRef, useState } from "react";

const services = [
  "Website Design",
  "Brand Strategy",
  "AI Automation",
  "Web Applications",
  "UI/UX Design",
  "3D Development",
  "SEO Optimization",
  "Maintenance",
];

const serviceImages: Record<string, string> = {
  "Website Design": "from-blue-900/30 to-purple-900/30",
  "Brand Strategy": "from-emerald-900/30 to-teal-900/30",
  "AI Automation": "from-violet-900/30 to-fuchsia-900/30",
  "Web Applications": "from-amber-900/30 to-orange-900/30",
  "UI/UX Design": "from-rose-900/30 to-pink-900/30",
  "3D Development": "from-cyan-900/30 to-blue-900/30",
  "SEO Optimization": "from-green-900/30 to-emerald-900/30",
  "Maintenance": "from-stone-900/30 to-zinc-900/30",
};

export default function Services() {
  const [active, setActive] = useState<number | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  return (
    <section
      id="services"
      ref={containerRef}
      className="relative min-h-screen px-6 md:px-16 py-24 border-t border-white/5"
    >
      <div className="max-w-7xl mx-auto">
        <span className="text-[11px] uppercase tracking-[0.3em] text-[#8B8B8B] font-mono">
          What We Do
        </span>

        <div className="grid lg:grid-cols-2 gap-12 lg:gap-24 mt-12">
          <div className="space-y-0">
            {services.map((service, i) => (
              <div
                key={i}
                className="service-item group py-6 cursor-pointer"
                onMouseEnter={() => setActive(i)}
                onMouseLeave={() => setActive(null)}
              >
                <div className="flex items-center justify-between">
                  <span className="font-hero text-4xl md:text-5xl lg:text-6xl tracking-tight group-hover:text-[#A3FF3F] transition-colors duration-300">
                    {service}
                  </span>
                  <span className="font-mono text-xs text-[#8B8B8B] group-hover:text-[#A3FF3F] transition-colors">
                    {String(i + 1).padStart(2, "0")}
                  </span>
                </div>
              </div>
            ))}
          </div>

          <div className="hidden lg:block relative">
            <div className="sticky top-32">
              <div
                className={`w-full aspect-square rounded-3xl bg-gradient-to-br transition-all duration-500 ${
                  active !== null
                    ? serviceImages[services[active!]]
                    : "from-[#111111] to-[#111111]"
                } border border-white/10 flex items-center justify-center`}
              >
                <div className="text-center p-8">
                  <span className="font-hero text-6xl text-white/10">
                    {active !== null ? String(active + 1).padStart(2, "0") : "//"}
                  </span>
                  <div className="mt-4 text-sm text-[#8B8B8B] font-mono">
                    {active !== null ? services[active] : "Hover a service"}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
