"use client";

import { useRef, useEffect } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

export default function Hero() {
  const containerRef = useRef<HTMLDivElement>(null);
  const stickyRef = useRef<HTMLHeadingElement>(null);

  useEffect(() => {
    const ctx = gsap.context(() => {
      gsap.fromTo(
        ".hero-line",
        { y: 120, opacity: 0 },
        {
          y: 0,
          opacity: 1,
          duration: 1.2,
          stagger: 0.15,
          ease: "power4.out",
          delay: 0.3,
        }
      );

      gsap.fromTo(
        ".hero-sub",
        { y: 40, opacity: 0 },
        { y: 0, opacity: 1, duration: 1, delay: 1, ease: "power3.out" }
      );

      gsap.fromTo(
        ".hero-btns",
        { y: 30, opacity: 0 },
        { y: 0, opacity: 1, duration: 0.8, delay: 1.3, ease: "power3.out" }
      );

      if (stickyRef.current) {
        gsap.to(stickyRef.current, {
          scale: 0.15,
          y: -window.innerHeight / 2 + 60,
          opacity: 0.6,
          scrollTrigger: {
            trigger: containerRef.current,
            start: "top top",
            end: "bottom top",
            scrub: 1.5,
          },
        });
      }
    });

    return () => ctx.revert();
  }, []);

  return (
    <section
      ref={containerRef}
      className="relative min-h-screen flex items-center justify-center px-6 md:px-16 overflow-hidden"
    >
      <div className="relative z-10 w-full max-w-7xl mx-auto flex flex-col lg:flex-row items-center justify-between gap-12 lg:gap-24">
        <div className="flex-1">
          <h1 className="font-hero text-[clamp(4rem,12vw,10rem)] leading-[0.85] tracking-tight">
            <div className="overflow-hidden">
              <span className="hero-line inline-block">WE DON&apos;T BUILD</span>
            </div>
            <div className="overflow-hidden">
              <span className="hero-line inline-block text-white/40">
                WEBSITES.
              </span>
            </div>
            <div className="overflow-hidden mt-4">
              <span className="hero-line inline-block">WE BUILD</span>
            </div>
            <div className="overflow-hidden">
              <span className="hero-line inline-block text-[#A3FF3F]">
                GROWTH.
              </span>
            </div>
          </h1>

          <h2
            ref={stickyRef}
            className="hero-sub font-hero text-3xl md:text-5xl text-[#A3FF3F] mt-6 origin-top-left"
          >
            WE BUILD GROWTH.
          </h2>
        </div>

        <div className="flex-1 max-w-md">
          <p className="hero-sub text-lg text-[#8B8B8B] leading-relaxed">
            GrowFrame designs digital experiences that transform ambitious
            businesses into unforgettable brands.
          </p>

          <div className="hero-btns flex flex-wrap gap-4 mt-8">
            <a
              href="#contact"
              className="magnetic-btn bg-[#A3FF3F] text-[#090909] font-medium rounded-full px-8 py-3 hover:bg-[#7CD628] transition-colors"
            >
              Start a Project &rarr;
            </a>
            <a
              href="#work"
              className="magnetic-btn border border-white/20 text-[#F8F8F8] rounded-full px-8 py-3 hover:border-[#A3FF3F]/50 transition-colors"
            >
              View Our Work
            </a>
          </div>
        </div>
      </div>

      <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-10 flex flex-col items-center gap-2">
        <span className="text-[10px] uppercase tracking-[0.3em] text-[#8B8B8B] font-mono">
          Scroll
        </span>
        <div className="w-px h-12 bg-gradient-to-b from-[#8B8B8B] to-transparent" />
      </div>
    </section>
  );
}
