"use client";

import { useRef, useEffect } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

export default function FinalCTA() {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const ctx = gsap.context(() => {
      gsap.fromTo(
        ".cta-content",
        { y: 80, opacity: 0 },
        {
          y: 0,
          opacity: 1,
          duration: 1,
          ease: "power3.out",
          scrollTrigger: {
            trigger: containerRef.current,
            start: "top 70%",
            toggleActions: "play none none reverse",
          },
        }
      );
    });

    return () => ctx.revert();
  }, []);

  return (
    <section
      id="contact"
      ref={containerRef}
      className="relative min-h-screen flex items-center justify-center px-6 md:px-16 py-24 border-t border-white/5 overflow-hidden"
    >
      {/* Abstract shapes background */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute top-1/4 left-1/4 w-64 h-64 bg-[#A3FF3F]/5 rounded-full blur-[100px] animate-pulse" />
        <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-[#A3FF3F]/3 rounded-full blur-[120px] animate-pulse" style={{ animationDelay: "1s" }} />
      </div>

      <div className="cta-content relative z-10 text-center">
        <span className="text-[11px] uppercase tracking-[0.3em] text-[#8B8B8B] font-mono">
          Let&apos;s Collaborate
        </span>

        <h2 className="font-hero text-[clamp(4rem,12vw,10rem)] leading-[0.85] mt-8">
          READY TO
          <br />
          <span className="text-[#A3FF3F]">GROW?</span>
        </h2>

        <div className="mt-12">
          <a
            href="#"
            className="magnetic-btn inline-flex items-center gap-3 bg-[#A3FF3F] text-[#090909] font-medium rounded-full px-10 py-4 text-lg hover:bg-[#7CD628] transition-colors group"
          >
            Let&apos;s Build
            <span className="group-hover:translate-x-1 transition-transform duration-200">
              &rarr;
            </span>
          </a>
        </div>
      </div>
    </section>
  );
}
