"use client";

import { useRef, useEffect } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

export default function Testimonials() {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const ctx = gsap.context(() => {
      gsap.fromTo(
        ".testimonial-content",
        { y: 60, opacity: 0 },
        {
          y: 0,
          opacity: 1,
          duration: 1,
          ease: "power3.out",
          scrollTrigger: {
            trigger: containerRef.current,
            start: "top 70%",
            toggleActions: "play none none reverse",
          },
        }
      );
    });

    return () => ctx.revert();
  }, []);

  return (
    <section
      ref={containerRef}
      className="relative min-h-screen flex items-center px-6 md:px-16 py-24 border-t border-white/5"
    >
      <div className="max-w-5xl mx-auto text-center">
        <span className="text-[11px] uppercase tracking-[0.3em] text-[#8B8B8B] font-mono">
          Testimonials
        </span>

        <div className="testimonial-content mt-16">
          <div className="text-[#A3FF3F] text-2xl mb-8">&ldquo;</div>

          <blockquote className="font-heading text-3xl md:text-5xl lg:text-6xl font-bold leading-[1.1]">
            &ldquo;Working with GrowFrame
            <br />
            completely transformed
            <br />
            <span className="text-[#A3FF3F]">our online presence.</span>&rdquo;
          </blockquote>

          <div className="flex justify-center gap-2 mt-8">
            {[...Array(5)].map((_, i) => (
              <span key={i} className="text-[#A3FF3F] text-2xl">
                &#9733;
              </span>
            ))}
          </div>

          <div className="mt-8">
            <p className="font-heading text-lg text-[#F8F8F8]">
              Sarah Chen
            </p>
            <p className="text-sm text-[#8B8B8B]">
              CEO, Mainframe Computers
            </p>
          </div>
        </div>
      </div>
    </section>
  );
}
