"use client";

import { useRef, useEffect } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

export default function CaseStudy() {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const ctx = gsap.context(() => {
      gsap.fromTo(
        ".case-stat",
        { y: 40, opacity: 0 },
        {
          y: 0,
          opacity: 1,
          duration: 0.8,
          stagger: 0.15,
          ease: "power3.out",
          scrollTrigger: {
            trigger: containerRef.current,
            start: "top 65%",
            toggleActions: "play none none reverse",
          },
        }
      );
    });

    return () => ctx.revert();
  }, []);

  return (
    <section
      ref={containerRef}
      className="relative min-h-screen flex items-center px-6 md:px-16 py-24 border-t border-white/5"
    >
      <div className="max-w-7xl mx-auto w-full">
        <span className="text-[11px] uppercase tracking-[0.3em] text-[#8B8B8B] font-mono">
          Case Study
        </span>

        <div className="mt-8 relative rounded-3xl overflow-hidden border border-white/10 bg-gradient-to-br from-[#A3FF3F]/5 via-[#111111] to-[#090909] min-h-[60vh] flex items-end p-8 md:p-16">
          <div className="relative z-10 w-full">
            <h3 className="font-hero text-5xl md:text-7xl lg:text-8xl text-[#F8F8F8]">
              Mainframe
              <br />
              <span className="text-[#A3FF3F]">Computers</span>
            </h3>

            <div className="grid grid-cols-2 md:grid-cols-3 gap-8 mt-12">
              <div className="case-stat">
                <div className="font-mono text-3xl md:text-4xl font-bold text-[#A3FF3F]">
                  42%
                </div>
                <div className="text-sm text-[#8B8B8B] mt-1">
                  Increase in inquiries
                </div>
              </div>
              <div className="case-stat">
                <div className="font-mono text-3xl md:text-4xl font-bold text-[#A3FF3F]">
                  3.5x
                </div>
                <div className="text-sm text-[#8B8B8B] mt-1">
                  More bookings
                </div>
              </div>
              <div className="case-stat col-span-2 md:col-span-1">
                <div className="font-mono text-3xl md:text-4xl font-bold text-[#A3FF3F]">
                  98
                </div>
                <div className="text-sm text-[#8B8B8B] mt-1">
                  Performance Score
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
